import { useEffect, type KeyboardEvent as ReactKeyboardEvent, type RefObject } from 'react'
import { isImeComposing } from './host-bridge'

export interface SlidingIndicatorOptions {
  itemSelector?: string
  indicatorClass?: string
}

const DEFAULT_ITEM_SELECTOR = '[role="tab"], button'
const DEFAULT_INDICATOR_CLASS = 'dsh-seg-ind'

function measureSelected(
  container: HTMLElement,
  itemSelector: string,
): { el: HTMLElement; left: number; width: number } | null {
  const candidates = Array.from(container.querySelectorAll<HTMLElement>(itemSelector))
  const sel = candidates.find((el) => el.getAttribute('aria-selected') === 'true')
  if (!sel) return null

  let width = sel.offsetWidth || 0
  let left = sel.offsetLeft || 0

  if (width === 0 && typeof sel.getBoundingClientRect === 'function') {
    const itemRect = sel.getBoundingClientRect()
    width = Math.round(itemRect.width)
    if (typeof container.getBoundingClientRect === 'function') {
      const parentRect = container.getBoundingClientRect()
      left = Math.round(itemRect.left - parentRect.left)
    }
  }

  return { el: sel, left, width }
}

/**
 * 08.2 滑动选中指示块（Segmented / UnderlineTabs / Popover 分类条通用）：
 * - 注入独立 aria-hidden 指示节点并挂载 data-ind 属性接管选中底；
 * - 首次挂载与 ResizeObserver 变化瞬时到位（无过渡动画）；
 * - aria-selected 切换时以 --dsh-dur-expand + --dsh-ease-out 驱动 transform 与 width 平滑滑动；
 * - 返回幂等 dispose() 断开观察器并移除节点。
 */
export function attachSlidingIndicator(
  container: HTMLElement,
  options?: SlidingIndicatorOptions,
): () => void {
  if (!container || !container.ownerDocument) return () => {}
  const doc = container.ownerDocument
  const win = doc.defaultView
  const itemSelector = options?.itemSelector ?? DEFAULT_ITEM_SELECTOR
  const indicatorClass = options?.indicatorClass ?? DEFAULT_INDICATOR_CLASS

  const ind = doc.createElement('span')
  ind.className = indicatorClass
  ind.setAttribute('aria-hidden', 'true')
  if (typeof container.prepend === 'function') {
    container.prepend(ind)
  } else {
    container.insertBefore(ind, container.firstChild)
  }
  container.setAttribute('data-ind', '')

  const expandTransition =
    'transform var(--dsh-dur-expand, 220ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1)), width var(--dsh-dur-expand, 220ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1))'

  let disposed = false
  const place = (instant: boolean) => {
    if (disposed) return
    const measured = measureSelected(container, itemSelector)
    if (!measured || measured.width <= 0) {
      ind.style.opacity = '0'
      return
    }
    if (instant) {
      ind.setAttribute('data-instant', '')
      ind.style.transition = 'none'
    } else {
      ind.removeAttribute('data-instant')
      ind.style.transition = expandTransition
    }
    ind.style.opacity = ''
    ind.style.setProperty('--ind-x', `${measured.left}px`)
    ind.style.setProperty('--ind-w', `${measured.width}px`)
    ind.style.width = `${measured.width}px`
    ind.style.transform = `translateX(${measured.left}px)`
    if (instant) {
      void ind.offsetWidth
      ind.removeAttribute('data-instant')
    }
  }

  const MutationCtor =
    (win as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  const mo = MutationCtor
    ? new MutationCtor(() => {
        place(false)
      })
    : null
  mo?.observe(container, {
    attributes: true,
    attributeFilter: ['aria-selected'],
    subtree: true,
  })

  const ResizeCtor =
    (win as unknown as { ResizeObserver?: typeof ResizeObserver } | null)?.ResizeObserver
    ?? globalThis.ResizeObserver
  const ro = ResizeCtor
    ? new ResizeCtor(() => {
        place(true)
      })
    : null
  ro?.observe(container)

  place(true)
  const fonts = (doc as unknown as { fonts?: { ready?: Promise<unknown> } }).fonts
  if (fonts?.ready) {
    void fonts.ready.then(() => {
      if (!disposed) place(true)
    })
  }

  return () => {
    if (disposed) return
    disposed = true
    mo?.disconnect()
    ro?.disconnect()
    ind.remove()
    container.removeAttribute('data-ind')
  }
}

function isIndicatorOptions(value: unknown): value is SlidingIndicatorOptions {
  if (typeof value !== 'object' || value === null) return false
  return 'itemSelector' in value || 'indicatorClass' in value
}

/**
 * React Hook 封装：在容器 ref 上自动绑定与清理滑动选中指示块。
 */
export function useSlidingIndicator(
  ref: RefObject<HTMLElement | null>,
  options?: SlidingIndicatorOptions,
): void
export function useSlidingIndicator(
  ref: RefObject<HTMLElement | null>,
  dep?: unknown,
  options?: SlidingIndicatorOptions,
): void
export function useSlidingIndicator(
  ref: RefObject<HTMLElement | null>,
  depOrOptions?: unknown,
  maybeOptions?: SlidingIndicatorOptions,
): void {
  const resolvedOptions =
    maybeOptions !== undefined
      ? maybeOptions
      : isIndicatorOptions(depOrOptions)
        ? depOrOptions
        : undefined
  const itemSelector = resolvedOptions?.itemSelector
  const indicatorClass = resolvedOptions?.indicatorClass

  useEffect(() => {
    const el = ref.current
    if (!el) return undefined
    return attachSlidingIndicator(el, { itemSelector, indicatorClass })
  }, [ref, itemSelector, indicatorClass])
}

const ROVING_KEYS = new Set([
  'ArrowRight',
  'ArrowDown',
  'ArrowLeft',
  'ArrowUp',
  'Home',
  'End',
])

/**
 * 08.1 Roving Tabindex 方向键漫游（← / → / ↑ / ↓ / Home / End）：
 * 自动跳过禁用与隐藏项，同步 tabindex="0/-1"，移动焦点并触发选中。
 */
export function handleRovingKeyDown(
  event: ReactKeyboardEvent<HTMLElement>,
  itemSelector: string = '[role="tab"], [role="radio"], button',
): void {
  if (isImeComposing(event)) return
  if (!ROVING_KEYS.has(event.key)) return

  const container = event.currentTarget
  if (!container) return
  const allItems = Array.from(container.querySelectorAll<HTMLElement>(itemSelector))
  const enabledItems = allItems.filter((el) => {
    if ((el as HTMLButtonElement).disabled) return false
    if (el.getAttribute('aria-disabled') === 'true') return false
    if (el.hidden || el.getAttribute('aria-hidden') === 'true') return false
    if (el.style?.display === 'none') return false
    return true
  })

  if (enabledItems.length === 0) return

  const doc = container.ownerDocument
  const activeEl = (doc?.activeElement ?? event.target) as Node | null
  let currentIndex = enabledItems.findIndex(
    (el) => el === activeEl || (activeEl !== null && typeof el.contains === 'function' && el.contains(activeEl)),
  )
  if (currentIndex < 0) {
    currentIndex = enabledItems.findIndex(
      (el) =>
        el.getAttribute('aria-selected') === 'true'
        || el.getAttribute('aria-checked') === 'true'
        || el.getAttribute('tabindex') === '0',
    )
  }
  if (currentIndex < 0) currentIndex = 0

  event.preventDefault()

  let nextIndex = currentIndex
  if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
    nextIndex = (currentIndex + 1) % enabledItems.length
  } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
    nextIndex = (currentIndex - 1 + enabledItems.length) % enabledItems.length
  } else if (event.key === 'Home') {
    nextIndex = 0
  } else if (event.key === 'End') {
    nextIndex = enabledItems.length - 1
  }

  const nextEl = enabledItems[nextIndex]
  if (!nextEl) return

  for (const item of allItems) {
    item.setAttribute('tabindex', item === nextEl ? '0' : '-1')
  }
  nextEl.focus?.()
  nextEl.click?.()
}
