/**
 * DSH 插件统一设计系统 Token（宿主 CDS 2.0 标尺 + @kewen/dsh-ui 动态语义扩展）。
 *
 * 设计原则：
 * 1. 主界面通用控件（按钮、菜单、弹窗、面板行、分段器、设置卡片）一律对齐宿主 --dsw-* 与扩展 --dsh-* 变量：
 *    - 圆角阶梯：xs=4px、sm=8px、md=12px、lg=16px、xl=20px、panel=28px、pill=999px。
 *    - 曲率双轨联动：常规圆角矩形统一写 corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round))；
 *      正圆（50%）与全圆弧胶囊（999px）必须显式写 corner-shape: round，防止被宿主默认超椭圆压成方圆。
 *      dsh-harness-plus 开启时在 html[data-hs-active] 注入 --dsh-corner-shape: round，绝不篡改 :root { --dsw-corner-shape }。
 *    - 语义表面与主色：全量由宿主 --dsw-* 在 oklab / oklch 空间动态混出，零孤立 Hex。
 * 2. 侧栏与壁纸感知表面（[data-hs]）采用 oklab 五阶交互底色锚定宿主侧栏变量，旧版 --hs-* 别名映射至官方语义变量保持兼容。
 *
 * 注意：CSS 模板字符串内部严禁出现反引号字符，以免截断模板或触发静态门禁报错。
 */

export const dshTokens = {
  radius: {
    /** 4px：行内微型图标按钮、小角标 */
    xs: 'var(--dsw-radius-xs, 4px)',
    /** 8px：菜单项、对话信息面板行、侧栏行、Tooltip */
    sm: 'var(--dsw-radius-sm, 8px)',
    /** 10px：兼容旧侧栏紧凑行引用 */
    row: 'var(--hs-r-row, 10px)',
    /** 12px：分组卡片 Card、横幅 Banner、空状态 EmptyState、多行文本域 Textarea、紧凑菜单 */
    md: 'var(--dsw-radius-md, 12px)',
    /** 16px：标准弹出菜单 MenuSurface、复合浮层 Popover、Modal 弹窗、RadioCard 外框 */
    lg: 'var(--dsw-radius-lg, 16px)',
    /** 20px：大号主题卡片、回复气泡 */
    xl: 'var(--dsw-radius-xl, 20px)',
    /** 28px：底部主输入框大面板 */
    panel: 'var(--dsw-radius-panel, 28px)',
    /** 全圆弧胶囊 / 开关轨道（需配合 corner-shape: round） */
    pill: '999px',
    /** 嵌套同心圆自动公式：父容器设 --dsh-r-outer 与 --dsh-pad，子元素自动取外圆角减边距 */
    concentric: 'max(0px, calc(var(--dsh-r-outer) - var(--dsh-pad)))',
    /** 内圆反推外框公式：已知内层胶囊半径 --dsh-r-inner 与边距 --dsh-pad */
    concentricOuter: 'calc(var(--dsh-r-inner) + var(--dsh-pad))',
  },
  corner: {
    /** 圆角矩形曲率联动钩子：Harness Plus 开启时走 --dsh-corner-shape（round 标准同心圆弧），关闭时回退宿主 --dsw-corner-shape */
    smooth: 'var(--dsh-corner-shape, var(--dsw-corner-shape, round))',
    /** 正圆与胶囊：覆盖宿主全局 superellipse(1.5)，保证 50% / 999px 不变方 */
    round: 'round',
  },
  border: {
    l1: '.5px solid var(--dsw-alias-border-l1)',
    l2: '.5px solid var(--dsw-alias-border-l2)',
    l3: '.5px solid var(--dsw-alias-border-l3)',
    l4: '.5px solid var(--dsw-alias-border-l4)',
  },
  elevation: {
    panel: 'var(--dsw-elevation-panel)',
    prominent: 'var(--dsw-elevation-prominent)',
    soft: 'var(--dsw-elevation-soft)',
  },
  text: {
    '2xs': 'var(--dsh-text-2xs, 10px)',
    xs: 'var(--dsh-text-xs, 11px)',
    sm: 'var(--dsh-text-sm, 12px)',
    md: 'var(--dsh-text-md, 13px)',
    lg: 'var(--dsh-text-lg, 14px)',
    xl: 'var(--dsh-text-xl, 16px)',
  },
  control: {
    xs: 'var(--dsh-control-xs, 20px)',
    sm: 'var(--dsh-control-sm, 28px)',
    md: 'var(--dsh-control-md, 36px)',
    lg: 'var(--dsh-control-lg, 44px)',
  },
  rowHeight: {
    sm: 'var(--dsh-row-sm, 32px)',
    md: 'var(--dsh-row-md, 44px)',
    lg: 'var(--dsh-row-lg, 48px)',
  },
  motion: {
    press: 'var(--dsh-dur-press, 60ms)',
    hover: 'var(--dsh-dur-hover, 120ms)',
    release: 'var(--dsh-dur-release, 150ms)',
    pop: 'var(--dsh-dur-pop, 150ms)',
    expand: 'var(--dsh-dur-expand, 220ms)',
    spin: 'var(--dsh-dur-spin, 800ms)',
    easeOut: 'var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1))',
  },
} as const

