function readHostVar(
  name: string,
  frameStyle: CSSStyleDeclaration | null,
  bodyStyle: CSSStyleDeclaration | null,
  rootStyle: CSSStyleDeclaration | null,
  hostDoc: Document,
): string {
  const candidates = [
    frameStyle?.getPropertyValue?.(name),
    bodyStyle?.getPropertyValue?.(name),
    rootStyle?.getPropertyValue?.(name),
    hostDoc.body?.style?.getPropertyValue?.(name),
    hostDoc.documentElement?.style?.getPropertyValue?.(name),
  ]
  for (const raw of candidates) {
    if (typeof raw === 'string') {
      const trimmed = raw.trim()
      if (trimmed !== '') return trimmed
    }
  }
  return ''
}

function resolveHostScheme(
  frameStyle: CSSStyleDeclaration | null,
  bodyStyle: CSSStyleDeclaration | null,
  hostDoc: Document,
  hostWin: Window | null,
): 'dark' | 'light' {
  if (hostDoc.body?.hasAttribute?.('data-ds-dark-theme')) return 'dark'
  const rootTheme = hostDoc.documentElement?.getAttribute?.('data-theme')
  if (rootTheme === 'dark' || rootTheme === 'light') return rootTheme
  const csScheme = (frameStyle?.getPropertyValue?.('color-scheme') || bodyStyle?.getPropertyValue?.('color-scheme') || '').trim()
  if (csScheme === 'dark' || csScheme === 'light') return csScheme
  if (hostWin?.matchMedia?.('(prefers-color-scheme: dark)').matches) return 'dark'
  return 'light'
}

function applyHostThemeToDocument(
  targetDoc: Document,
  hostDoc: Document,
  frame: HTMLIFrameElement,
): 'dark' | 'light' {
  const targetRoot = targetDoc.documentElement
  const hostWin = hostDoc.defaultView
  const getCS = hostWin?.getComputedStyle?.bind(hostWin)
  const frameStyle = getCS ? getCS(frame) : null
  const bodyStyle = getCS && hostDoc.body ? getCS(hostDoc.body) : null
  const rootStyle = getCS && hostDoc.documentElement ? getCS(hostDoc.documentElement) : null

  const hsActive = Boolean(hostDoc.documentElement?.hasAttribute?.('data-hs-active'))
  if (hsActive) targetRoot.setAttribute('data-hs-active', '')
  else targetRoot.removeAttribute('data-hs-active')

  for (const name of HOST_SYNC_VARS) {
    if (name === '--dsh-corner-shape') {
      const explicit = readHostVar(name, frameStyle, bodyStyle, rootStyle, hostDoc)
      if (explicit !== '') {
        targetRoot.style.setProperty(name, explicit)
      } else if (hsActive) {
        targetRoot.style.setProperty(name, 'round')
      } else {
        targetRoot.style.removeProperty(name)
      }
      continue
    }
    const val = readHostVar(name, frameStyle, bodyStyle, rootStyle, hostDoc)
    if (val !== '') targetRoot.style.setProperty(name, val)
    else targetRoot.style.removeProperty(name)
  }

  const font = readHostVar('font-family', frameStyle, bodyStyle, rootStyle, hostDoc)
  if (font !== '') {
    targetRoot.style.setProperty('--xp-host-font', font)
  }

  const scheme = resolveHostScheme(frameStyle, bodyStyle, hostDoc, hostWin)
  targetRoot.setAttribute('data-theme', scheme)
  if (targetRoot.dataset) targetRoot.dataset.theme = scheme
  targetRoot.style.colorScheme = scheme

  const hostDarkAttr = Boolean(hostDoc.body?.hasAttribute?.('data-ds-dark-theme')) || scheme === 'dark'
  if (targetDoc.body) {
    if (hostDarkAttr) targetDoc.body.setAttribute('data-ds-dark-theme', '')
    else targetDoc.body.removeAttribute('data-ds-dark-theme')
    targetDoc.body.style.colorScheme = scheme
  }

  const platform =
    frame.closest?.('[data-platform]')?.getAttribute('data-platform')
    ?? hostDoc.documentElement?.getAttribute?.('data-platform')
    ?? hostDoc.body?.getAttribute?.('data-platform')
    ?? null
  if (platform) {
    targetRoot.setAttribute('data-platform', platform)
    if (targetRoot.dataset) targetRoot.dataset.platform = platform
  } else {
    targetRoot.removeAttribute('data-platform')
    if (targetRoot.dataset) delete targetRoot.dataset.platform
  }

  return scheme
}

/**
 * 父窗口侧：将宿主 --dsw-*、--dsh-corner-shape、data-hs-active、data-ds-dark-theme、colorScheme、data-platform
 * 实时同步进同源子 <iframe> 文档（支持 load 重同步与外层 MutationObserver 实时联动）。
 */
export function syncHostThemeToIframe(iframe: HTMLIFrameElement): () => void {
  const hostDoc = iframe?.ownerDocument
  if (!hostDoc || !hostDoc.documentElement) return () => {}
  const hostWin = hostDoc.defaultView

  const syncNow = () => {
    try {
      const childDoc = iframe.contentDocument
      if (!childDoc || !childDoc.documentElement) return
      childDoc.documentElement.setAttribute('data-embed', '')
      if (childDoc.documentElement.dataset) childDoc.documentElement.dataset.embed = ''
      applyHostThemeToDocument(childDoc, hostDoc, iframe)
    } catch {
      /* 跨源或子页面卸载期间静默忽略 */
    }
  }

  syncNow()
  iframe.addEventListener?.('load', syncNow)

  const ObserverCtor =
    (hostWin as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  const mo = ObserverCtor ? new ObserverCtor(() => syncNow()) : null
  if (mo) {
    mo.observe(hostDoc.documentElement, { attributes: true })
    if (hostDoc.body) mo.observe(hostDoc.body, { attributes: true })
  }

  const mq = hostWin?.matchMedia ? hostWin.matchMedia('(prefers-color-scheme: dark)') : null
  mq?.addEventListener?.('change', syncNow)

  let disposed = false
  return () => {
    if (disposed) return
    disposed = true
    mo?.disconnect()
    iframe.removeEventListener?.('load', syncNow)
    mq?.removeEventListener?.('change', syncNow)
  }
}

function getSameOriginHostFrame(win: Window): HTMLIFrameElement | null {
  try {
    if (!win.parent || win.parent === win) return null
    const frame = win.frameElement as HTMLIFrameElement | null
    return frame && frame.ownerDocument ? frame : null
  } catch {
    return null
  }
}

function resolveStandaloneScheme(win: Window): 'dark' | 'light' {
  try {
    const search = win.location?.search ?? ''
    const forced = new URLSearchParams(search).get('theme')
    if (forced === 'dark' || forced === 'light') return forced
  } catch {
    /* ignore invalid location */
  }
  return win.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

/**
 * 子页面侧：同源嵌入 DSH 时实时镜像外层宿主主题与曲率双轨；单独在浏览器打开时自动回退系统深浅色与 ?theme= 参数。
 */
export function startIframeThemeSync(win?: Window): () => void {
  const targetWin = win ?? (typeof window !== 'undefined' ? window : undefined)
  if (!targetWin || !targetWin.document || !targetWin.document.documentElement) return () => {}

  const doc = targetWin.document
  const root = doc.documentElement
  const frame = getSameOriginHostFrame(targetWin)

  if (frame === null) {
    root.setAttribute('data-standalone', '')
    if (root.dataset) root.dataset.standalone = ''
    const applyStandalone = () => {
      const scheme = resolveStandaloneScheme(targetWin)
      root.setAttribute('data-theme', scheme)
      if (root.dataset) root.dataset.theme = scheme
      root.style.colorScheme = scheme
      if (doc.body) {
        if (scheme === 'dark') doc.body.setAttribute('data-ds-dark-theme', '')
        else doc.body.removeAttribute('data-ds-dark-theme')
        doc.body.style.colorScheme = scheme
      }
    }
    applyStandalone()
    const mq = targetWin.matchMedia ? targetWin.matchMedia('(prefers-color-scheme: dark)') : null
    mq?.addEventListener?.('change', applyStandalone)
    let disposed = false
    return () => {
      if (disposed) return
      disposed = true
      mq?.removeEventListener?.('change', applyStandalone)
    }
  }

  root.setAttribute('data-embed', '')
  if (root.dataset) root.dataset.embed = ''
  const hostDoc = frame.ownerDocument
  const hostWin = hostDoc.defaultView

  const sync = () => {
    try {
      applyHostThemeToDocument(doc, hostDoc, frame)
    } catch {
      /* 宿主正在卸载 */
    }
  }

  sync()

  const ObserverCtor =
    (targetWin as unknown as { MutationObserver?: typeof MutationObserver }).MutationObserver
    ?? (hostWin as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  const mo = ObserverCtor ? new ObserverCtor(() => sync()) : null
  if (mo) {
    mo.observe(hostDoc.documentElement, { attributes: true })
    if (hostDoc.body) mo.observe(hostDoc.body, { attributes: true })
  }

  const onMessage = (e: MessageEvent) => {
    const sameOrigin = !targetWin.location?.origin || e.origin === targetWin.location.origin
    if (
      sameOrigin
      && e.data
      && (e.data.type === 'DSH_EXT_THEME' || e.data.type === 'DSH_THEME_SYNC')
    ) {
      sync()
    }
  }
  targetWin.addEventListener?.('message', onMessage)

  const mq = hostWin?.matchMedia ? hostWin.matchMedia('(prefers-color-scheme: dark)') : null
  mq?.addEventListener?.('change', sync)

  let disposed = false
  return () => {
    if (disposed) return
    disposed = true
    mo?.disconnect()
    targetWin.removeEventListener?.('message', onMessage)
    mq?.removeEventListener?.('change', sync)
  }
}

/**
 * 主题 / 曲率切换瞬态锁：执行切换前挂载 html[data-dsh-theme-switching] 阻断全树 transition，
 * 双 requestAnimationFrame 后自动移除，彻底杜绝组件不同步渐变残影。
 */
export function withThemeSnap(fn: () => void, doc?: Document): void {
  const targetDoc = doc ?? (typeof document !== 'undefined' ? document : undefined)
  const root = targetDoc?.documentElement
  if (!root) {
    fn()
    return
  }

  root.setAttribute('data-dsh-theme-switching', '')
  try {
    fn()
    if (targetDoc?.body) {
      void (targetDoc.body as HTMLElement).offsetHeight
    }
  } finally {
    const raf =
      targetDoc?.defaultView?.requestAnimationFrame?.bind(targetDoc.defaultView)
      ?? (typeof requestAnimationFrame === 'function' ? requestAnimationFrame : undefined)
    if (raf) {
      raf(() => {
        raf(() => {
          root.removeAttribute('data-dsh-theme-switching')
        })
      })
    } else {
      queueMicrotask(() => {
        root.removeAttribute('data-dsh-theme-switching')
      })
    }
  }
}

export interface ImeGuardEventLike {
  isComposing?: boolean
  keyCode?: number
  nativeEvent?: {
    isComposing?: boolean
    keyCode?: number
  }
}

/**
 * CJK 输入法选词态守卫：兼容原生 KeyboardEvent 与 React SyntheticEvent（isComposing === true || keyCode === 229）。
 */
export function isImeComposing(event: ImeGuardEventLike | null | undefined): boolean {
  if (!event) return false
  if (event.isComposing === true || event.keyCode === 229) return true
  if (event.nativeEvent?.isComposing === true || event.nativeEvent?.keyCode === 229) return true
  return false
}

const dragRefCounts = new WeakMap<Element, number>()

/**
 * 全局拖拽防吞指针盾：按根节点做引用计数维护 html[data-dsh-dragging]，
 * 分屏条或浮窗拖拽期间全局锁定 user-select: none 与 iframe { pointer-events: none !important }。
 */
export function beginGlobalDrag(doc?: Document): () => void {
  const targetDoc = doc ?? (typeof document !== 'undefined' ? document : undefined)
  const root = targetDoc?.documentElement
  if (!root) return () => {}

  const prev = dragRefCounts.get(root) ?? 0
  dragRefCounts.set(root, prev + 1)
  root.setAttribute('data-dsh-dragging', '')

  let ended = false
  return () => {
    if (ended) return
    ended = true
    const current = dragRefCounts.get(root) ?? 1
    const next = Math.max(0, current - 1)
    if (next === 0) {
      dragRefCounts.delete(root)
      root.removeAttribute('data-dsh-dragging')
    } else {
      dragRefCounts.set(root, next)
    }
  }
}
